SELECT CASE WHEN d.budget >= 4403000 THEN 'high' WHEN d.budget >= 906000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND(AVG(e.salary), 2) AS avg_salary, MIN(e.salary) AS min_salary FROM employees e INNER JOIN departments d ON e.dept_id = d.id WHERE d.location IN ('Chiang Mai', 'New York') GROUP BY CASE WHEN d.budget >= 4403000 THEN 'high' WHEN d.budget >= 906000 THEN 'mid' ELSE 'low' END;
